const inputData = $input.first().json;
let rawText = "";

if (inputData.content && inputData.content.parts && inputData.content.parts[0].text) {
    rawText = inputData.content.parts[0].text;
} else if (inputData.text) {
    rawText = inputData.text;
} else if (inputData.candidates && inputData.candidates[0].content.parts[0].text) {
    rawText = inputData.candidates[0].content.parts[0].text;
} else {
    throw new Error("لم يتم العثور على النص! الرجاء التحقق من مخرجات عقدة الذكاء الاصطناعي.");
}

// Clean markdown
rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

const parsedData = JSON.parse(rawText);
let transactionsArray = Array.isArray(parsedData) ? parsedData : [parsedData];

const execId = ($execution && $execution.id) ? $execution.id : Math.random().toString(36).substring(2, 8);
let chatId = 0;
try {
    chatId = $('When Executed by Another Workflow').item.json.message.chat.id;
} catch(e) {
    chatId = 0;
}

let parentTaskId = "";

return transactionsArray.map((item, index) => {
    item.telegram_chat_id = chatId;

    if (item.record_type === 'Task') {
        if (!item.parent_task_id || item.parent_task_id === "") {
            parentTaskId = `T-${execId.slice(-5)}`;
            item.task_id = parentTaskId;
            item.parent_task_id = "";
        } else if (item.parent_task_id === "PARENT") {
            item.task_id = `${parentTaskId}-${index}`;
            item.parent_task_id = parentTaskId;
        }
    } else if (item.record_type === 'Habit') {
        item.habit_id = `H-${execId.slice(-4)}`;
        item.current_streak = 0;
        item.best_streak = 0;
        item.status = "Pending";
    }

    return { json: item };
});

const items = $input.all();
let summaryText = "💰 ملخص المصروفات:\n\n";
let totalAmount = 0;

const sharedIdentifier = items[0].json.row_id || items[0].json.row_number;

items.forEach((item, index) => {
    const t = item.json;
    const name = t.item_name ? t.item_name : (t.category || "عنصر غير محدد");
    const itemNotes = t.notes ? ` (${t.notes})` : "";
    const qtyText = (t.quantity && t.quantity > 1) ? ` - العدد: ${t.quantity}` : "";
    summaryText += `${index + 1}. ${name}${itemNotes}${qtyText} - ${t.amount} ${t.currency}\n`;
    totalAmount += Number(t.amount);
});

summaryText += `\n💰 الإجمالي: ${totalAmount} ${items[0].json.currency}`;

return [{
    json: {
        summary_text: summaryText,
        row_id: sharedIdentifier,
        record_type: "Expense"
    }
}];

const items = $input.all();
let summaryText = "🏋️ ملخص التمرين:\n\n";

const sharedIdentifier = items[0].json.row_id || items[0].json.row_number;

items.forEach((item, index) => {
    const t = item.json;
    const exercise = t.exercise_name || "تمرين غير محدد";
    const muscle = t.muscle_group ? ` (${t.muscle_group})` : "";
    const setsReps = (t.sets && t.reps) ? ` — ${t.sets} سيت × ${t.reps} تكرار` : "";
    const weightInfo = t.weight ? ` — ${t.weight} ${t.weight_unit || 'kg'}` : "";
    summaryText += `${index + 1}. ${exercise}${muscle}${setsReps}${weightInfo}\n`;
});

return [{
    json: {
        summary_text: summaryText,
        row_id: sharedIdentifier,
        record_type: "Gym"
    }
}];

const items = $input.all();
let summaryText = "📖 ملخص الورد:\n\n";

const sharedIdentifier = items[0].json.row_id || items[0].json.row_number;

items.forEach((item, index) => {
    const t = item.json;
    const surah = t.surah_name || "سورة غير محددة";
    const ayahRange = (t.start_ayah && t.end_ayah) ? ` — من الآية ${t.start_ayah} إلى ${t.end_ayah}` : "";
    const pages = t.pages_read ? ` — ${t.pages_read} صفحة` : "";
    summaryText += `${index + 1}. سورة ${surah}${ayahRange}${pages}\n`;
});

return [{
    json: {
        summary_text: summaryText,
        row_id: sharedIdentifier,
        record_type: "Quran"
    }
}];

const items = $input.all();
const parent = items.find(i => !i.json.parent_task_id) || items[0];
const subtasks = items.filter(i => i.json.parent_task_id);

const sharedIdentifier = parent.json.row_id || parent.json.task_id || items[0].json.row_id || ($execution ? $execution.id : 'task-1');

let summaryText = `✅ *ملخص المهام:*\n\n`;
summaryText += `🎯 *${parent.json.task_description}*\n`;
if (parent.json.priority) summaryText += `⚡ الأولوية: ${parent.json.priority}\n`;
if (parent.json.due_date && parent.json.due_date !== 'Unspecified') summaryText += `📅 الموعد: ${parent.json.due_date}\n`;
if (parent.json.estimated_minutes) summaryText += `⏱️ الوقت المقدر: ${parent.json.estimated_minutes} دقيقة\n`;

if (subtasks.length > 0) {
    summaryText += `\n📌 *الخطوات المقترحة (WBS):*\n`;
    subtasks.forEach((st, idx) => {
        const time = st.json.estimated_minutes ? ` (${st.json.estimated_minutes} د)` : '';
        const due = (st.json.due_date && st.json.due_date !== 'Unspecified') ? ` — ${st.json.due_date}` : '';
        summaryText += `${idx + 1}. [ ] ${st.json.task_description}${time}${due}\n`;
    });
}

return [{
    json: {
        summary_text: summaryText,
        row_id: sharedIdentifier,
        record_type: "Task"
    }
}];

const item = $input.first().json;
let summaryText = `🎯 *تم إعداد عادة جديدة:*\n\n`;
summaryText += `✨ *${item.habit_name}*\n`;
summaryText += `⏱️ المدة اليومية: ${item.target_minutes || 15} دقيقة\n`;
summaryText += `⏰ وقت التذكير: ${item.reminder_time || '20:00'}\n`;
summaryText += `🔁 التكرار: ${item.frequency || 'يومياً'}\n`;
summaryText += `🏷️ التصنيف: ${item.category || 'تطوير ذاتي'}\n\n`;
summaryText += `💡 *اضغط تأكيد لتفعيل التذكير الآلي وبدء احتساب الـ Streak!* 🔥`;

return [{
    json: {
        summary_text: summaryText,
        row_id: item.habit_id,
        record_type: "Habit"
    }
}];
